//! Statistics conformance: Wilson endpoints, point estimates and rounding
//! against vectors computed independently of the implementation.
//!
//! The expected values in `vectors/wilson_vectors.rs` were generated by
//! `vectors/wilson_reference.py`: the textbook formula in Python `decimal` at
//! 120 digits, rounded once half up. That script shares no code or algebra with
//! the kernel (which uses exact integer arithmetic), and was run once; CI does
//! not run Python. Zero samples, zero failures, all failures, very large counts
//! and tiny strata are covered by the table and by the explicit tests below.

use pii_eval_contracts::{BoundDirection, Mechanics, MetricValue, ScaledDecimal, WithheldReason};
use pii_eval_kernel::{published_value, round_ratio, wilson_mantissa};

include!("vectors/wilson_vectors.rs");

fn z(mantissa: u64, scale: u8) -> ScaledDecimal {
    ScaledDecimal { mantissa, scale }
}

#[test]
fn every_independent_vector_matches() {
    assert!(WILSON_VECTORS.len() >= 38);
    for &(k, n, zm, zs, places, point, upper, lower) in WILSON_VECTORS {
        let case = format!("k={k} n={n} z={zm}e-{zs} places={places}");
        assert_eq!(round_ratio(k, n, places), Ok(point), "point {case}");
        assert_eq!(
            wilson_mantissa(k, n, BoundDirection::Upper, z(zm, zs), places),
            Ok(upper),
            "upper {case}"
        );
        assert_eq!(
            wilson_mantissa(k, n, BoundDirection::Lower, z(zm, zs), places),
            Ok(lower),
            "lower {case}"
        );
    }
}

#[test]
fn ordering_and_range_hold_for_every_small_count() {
    let m = Mechanics::PII_V1;
    for n in 1..=60u64 {
        let mut previous_upper = 0;
        let mut previous_lower = 0;
        for k in 0..=n {
            let point = round_ratio(k, n, 6).unwrap();
            let upper = wilson_mantissa(k, n, BoundDirection::Upper, m.interval_z, 6).unwrap();
            let lower = wilson_mantissa(k, n, BoundDirection::Lower, m.interval_z, 6).unwrap();
            assert!(lower <= point && point <= upper, "k={k} n={n}");
            assert!(upper <= 1_000_000, "k={k} n={n}");
            // Monotone in the numerator.
            assert!(
                upper >= previous_upper && lower >= previous_lower,
                "k={k} n={n}"
            );
            previous_upper = upper;
            previous_lower = lower;
        }
        // Zero failures: the lower endpoint is exactly 0; all failures: the upper is exactly 1.
        assert_eq!(
            wilson_mantissa(0, n, BoundDirection::Lower, m.interval_z, 6),
            Ok(0)
        );
        assert_eq!(
            wilson_mantissa(n, n, BoundDirection::Upper, m.interval_z, 6),
            Ok(1_000_000)
        );
    }
}

#[test]
fn the_interval_narrows_as_the_sample_grows() {
    let m = Mechanics::PII_V1;
    // 25 percent failures at growing N: the pessimistic upper bound falls toward 0.25.
    let mut previous = u64::MAX;
    for n in [4u64, 40, 400, 4_000, 4_000_000, 4_000_000_000] {
        let upper = wilson_mantissa(n / 4, n, BoundDirection::Upper, m.interval_z, 12).unwrap();
        assert!(upper < previous, "n={n}");
        assert!(upper > 250_000_000_000, "n={n}");
        previous = upper;
    }
}

#[test]
fn zero_denominator_and_minimum_denominator_are_distinct_withheld_reasons() {
    let m = Mechanics::PII_V1; // minDenominator 4
    let up = BoundDirection::Upper;
    assert_eq!(
        published_value(0, 0, up, &m),
        Ok(MetricValue::Withheld {
            reason: WithheldReason::ZeroDenominator
        })
    );
    for n in 1..4 {
        assert_eq!(
            published_value(0, n, up, &m),
            Ok(MetricValue::Withheld {
                reason: WithheldReason::InsufficientEvidence
            }),
            "n={n}"
        );
    }
    let at_floor = published_value(1, 4, up, &m).unwrap();
    assert_eq!(
        at_floor,
        MetricValue::Measured {
            point: ScaledDecimal::new(250_000, 6).unwrap(),
            bound: ScaledDecimal::new(699_364, 6).unwrap(),
        }
    );
    // A larger floor moves the threshold; the mechanics are part of the identity.
    let strict = Mechanics {
        min_denominator: 10,
        ..m
    };
    assert_eq!(
        published_value(1, 9, up, &strict),
        Ok(MetricValue::Withheld {
            reason: WithheldReason::InsufficientEvidence
        })
    );
    assert!(matches!(
        published_value(1, 10, up, &strict),
        Ok(MetricValue::Measured { .. })
    ));
}

#[test]
fn published_decimals_are_normalized_and_within_precision() {
    let m = Mechanics::PII_V1;
    for n in 4..=40u64 {
        for k in 0..=n {
            for dir in [BoundDirection::Upper, BoundDirection::Lower] {
                match published_value(k, n, dir, &m).unwrap() {
                    MetricValue::Measured { point, bound } => {
                        for d in [point, bound] {
                            assert!(d.is_normalized(), "k={k} n={n}");
                            assert!(d.is_at_most_one(), "k={k} n={n}");
                            assert!(d.scale <= m.interval_precision, "k={k} n={n}");
                        }
                    }
                    other => panic!("n={n} is above the floor: {other:?}"),
                }
            }
        }
    }
}

#[test]
fn large_counts_never_panic_or_overflow_within_contract_limits() {
    let m = Mechanics::PII_V1;
    let max = (1u64 << 53) - 1;
    for n in [4, 1 << 20, 1 << 32, 1 << 40, max] {
        for k in [0, 1, n / 3, n / 2, n - 1, n] {
            for dir in [BoundDirection::Upper, BoundDirection::Lower] {
                assert!(matches!(
                    published_value(k, n, dir, &m),
                    Ok(MetricValue::Measured { .. })
                ));
            }
        }
    }
    // A numerator above the effective N is an error, never a clamp.
    assert!(published_value(max, max - 1, BoundDirection::Upper, &m).is_err());
}

#[test]
fn identical_inputs_give_identical_output_on_repeat() {
    let m = Mechanics::PII_V1;
    let runs: Vec<_> = (0..5)
        .map(|_| {
            (0..=50u64)
                .map(|k| published_value(k, 50, BoundDirection::Upper, &m).unwrap())
                .collect::<Vec<_>>()
        })
        .collect();
    assert!(runs.windows(2).all(|w| w[0] == w[1]));
}
